#include <stdio.h>
#include <stdlib.h>

typedef struct Node { int data; struct Node *next; } Node;

int main(void) {
    printf("sizeof(int)          = %zu 字节\n", sizeof(int));
    printf("sizeof(struct Node*) = %zu 字节\n", sizeof(Node *));
    printf("sizeof(struct Node)  = %zu 字节  <- 数据4B + 指针8B + 对齐填充4B\n",
           sizeof(Node));

    int n = 1000;
    printf("\n存 %d 个 int 的数组： %zu 字节\n", n, (size_t)n * sizeof(int));
    printf("存 %d 个 int 的链表： %zu 字节（仅节点本身）\n",
           n, (size_t)n * sizeof(Node));
    printf("节点数组倍数 ≈ %.1fx；再叠加 malloc 元数据(每节点约16~32B)，实际可达 5~10x\n",
           (double)(n * sizeof(Node)) / (n * sizeof(int)));
    printf("\n结论：内存密度低 → cache line 装不下几个节点 → 遍历更慢\n");
    return 0;
}
